package com.procurement.rfq.entity;
import com.procurement.purchaserequest.entity.PurchaseRequest; import jakarta.persistence.*; import lombok.*; import java.time.*;
@Entity @Table(name="rfqs",uniqueConstraints=@UniqueConstraint(columnNames="rfq_number")) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Rfq { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="rfq_id") private Long id; @Column(name="rfq_number",nullable=false,length=40) private String rfqNumber; @OneToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="purchase_request_id",nullable=false,unique=true) private PurchaseRequest purchaseRequest; @Column(name="issue_date",nullable=false) private LocalDate issueDate; @Column(name="closing_date",nullable=false) private LocalDate closingDate; @Column(name="quotation_opening_date",nullable=false) private LocalDate quotationOpeningDate; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private RfqStatus status; @Column(length=1000) private String remarks; @Column(name="created_by",nullable=false,length=100) private String createdBy; @Column(name="updated_by",length=100) private String updatedBy; @Column(name="created_at",updatable=false) private LocalDateTime createdAt; @Column(name="updated_at") private LocalDateTime updatedAt; @PrePersist void pre(){var n=LocalDateTime.now();createdAt=n;updatedAt=n;if(status==null)status=RfqStatus.DRAFT;} @PreUpdate void upd(){updatedAt=LocalDateTime.now();} }
